cards.solution:
type Todo = { readonly id: number; judul: string; selesai: boolean };
const daftar: Todo[] = [
  { id: 1, judul: "Belajar", selesai: true },
  { id: 2, judul: "Olahraga", selesai: false },
  { id: 3, judul: "Masak", selesai: true },
];
function ringkas(daftar: Todo[]): string {
  const selesai = daftar.filter((t) => t.selesai).length;
  return `${selesai}/${daftar.length} selesai`;
}
console.log(ringkas(daftar));
